def anpath_gps_trajectory(change):
  if change['type'] == 'change' and change['new'] == True:
    table = gps_crs[gps_crs["pick_up"] == dropdown_pickup.value]
    antpath_list = []
    for i in set(table['Vehicle']):
      single_run = table[table['Vehicle'] == i].sort_values(by = 'Time')
      results = single_run[['Lat', 'Lon']].to_numpy().tolist()
      antpath_list.append(results)
    for item in myMap.layers:
      if isinstance(item,ipyleaflet.leaflet.AntPath):
        item.locations = antpath_list
  if change['type'] == 'change' and change['new'] == False:
    for item in myMap.layers:
      if isinstance(item,ipyleaflet.leaflet.AntPath):
        item.locations = []
